  const svgFuente = SV(150, `<rect x="20" y="10" width="200" height="120" rx="12" fill="none" stroke="currentColor" stroke-width="2"/>${lcd(30, 22, 85, '12,00', 'V')}${lcd(125, 22, 85, '012', 'mA')}
    <circle cx="70" cy="96" r="14" fill="none" stroke="currentColor" stroke-width="2"/><path d="M70 96l6 -10" stroke="var(--led)" stroke-width="3"/>${tx(70, 124, 'tensión', 'vizsm', mid)}<circle cx="165" cy="96" r="14" fill="none" stroke="currentColor" stroke-width="2"/><path d="M165 96l-8 -8" stroke="var(--led)" stroke-width="3"/>${tx(165, 124, 'límite I', 'vizsm', mid)}
    <circle cx="245" cy="40" r="7" fill="var(--ok)"/>${tx(256, 44, 'CV', 'vizlab')}<circle cx="245" cy="70" r="7" fill="var(--line)"/>${tx(256, 74, 'CC', 'vizlab')}`);
  const svgLedFuente = SV(110, `<rect x="20" y="20" width="100" height="60" rx="10" fill="none" stroke="currentColor" stroke-width="2"/>${tx(70, 44, '3 V', 'vizlab', mid)}${tx(70, 64, 'límite 10 mA', 'vizsm', mid)}<path d="M120 35H220V70M220 70V80H120" ${st}/>${ledSym(220, 58)}<circle cx="220" cy="58" r="20" fill="#E5484D" opacity=".3"/>${tx(150, 102, 'En CC la fuente limita: útil para probar', 'vizsm', mid)}`);
  const svgPasos = SV(170, `${['1 · Punta en pad y pata', '2 · Estaño a la unión', '3 · Retira el estaño', '4 · Retira la punta', '5 · Corta la pata'].map((s, i) => `<g class="a-fade a-d${(i % 4) + 1}"><circle cx="24" cy="${20 + i * 32}" r="10" fill="var(--led)"/>${tx(24, 24 + i * 32, i + 1, 'vizlab', mid + ' style="fill:#fff"')}${tx(44, 24 + i * 32, s.slice(4), 'vizlab')}</g>`).join('')}${tx(290, 90, '2–3 s', 'vizbig', end)}`);
